// spec: specs/guides-videos.md (1.6) · кейс: .qa/tests/guides-videos/GUIDES-04.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение (HTTP GET). Разбор контейнера MP4: mvhd (длительность),
// hdlr (vide/soun), stsd (avc1/mp4a). Дорожка есть ≠ слышна речь — речь проверяется вручную (GUIDES-07).
import { test, expect } from '@playwright/test';

const GUIDES = [
  // Длительности принятой версии 2026-11-04 (signup/search — PR #194; home/area/publish — PR #196, приёмка #4abcf4;
  // ffmpeg: 104,7 / 72,8 / 126,4 / 121,5 / 123,4 с).
  { id: 'home', seconds: 105 },
  { id: 'signup', seconds: 73 },
  { id: 'publish', seconds: 126 },
  { id: 'search', seconds: 122 },
  { id: 'area', seconds: 123 },
] as const;
const TOLERANCE = 3;
const CONTAINERS = new Set(['moov', 'trak', 'mdia', 'minf', 'stbl']);

type Box = { type: string; start: number; size: number; header: number };

function readBoxes(buf: Buffer, from: number, to: number, out: Box[] = []): Box[] {
  let o = from;
  while (o + 8 <= to) {
    let size = buf.readUInt32BE(o);
    const type = buf.toString('latin1', o + 4, o + 8);
    let header = 8;
    if (size === 1) {
      size = Number(buf.readBigUInt64BE(o + 8));
      header = 16;
    } else if (size === 0) size = to - o;
    if (size < header) break;
    out.push({ type, start: o, size, header });
    if (CONTAINERS.has(type)) readBoxes(buf, o + header, Math.min(o + size, to), out);
    o += size;
  }
  return out;
}

function parseMp4(buf: Buffer) {
  const boxes = readBoxes(buf, 0, buf.length);
  const mvhd = boxes.find((b) => b.type === 'mvhd');
  if (!mvhd) throw new Error('в mp4 нет moov/mvhd');
  const p = mvhd.start + mvhd.header;
  const version = buf[p];
  const timescale = version ? buf.readUInt32BE(p + 20) : buf.readUInt32BE(p + 12);
  const duration = version ? Number(buf.readBigUInt64BE(p + 24)) : buf.readUInt32BE(p + 16);
  // hdlr: header + version/flags(4) + pre_defined(4) → handler_type
  const handlers = boxes.filter((b) => b.type === 'hdlr').map((b) => buf.toString('latin1', b.start + b.header + 8, b.start + b.header + 12));
  // stsd: header + version/flags(4) + entry_count(4) + entry size(4) → формат первой записи
  const codecs = boxes.filter((b) => b.type === 'stsd').map((b) => buf.toString('latin1', b.start + b.header + 12, b.start + b.header + 16));
  return { seconds: duration / timescale, handlers, codecs };
}

test.describe('Видео-инструкции /guides — файлы видео и постеров', () => {
  for (const g of GUIDES) {
    test(`${g.id}: mp4 и постер отдаются, длительность ≈ ${g.seconds} с, есть видео- и звуковая дорожка #8790d6 #d012a3 #92bc03 #94553b #66ad36 #d152dd @desktop @prod-safe`, async ({ request }) => {
      const poster = await request.get(`/guides/${g.id}.jpg`);
      expect(poster.status(), `постер /guides/${g.id}.jpg`).toBe(200);
      expect(poster.headers()['content-type'] ?? '').toMatch(/^image\//);

      const video = await request.get(`/guides/${g.id}.mp4`, { timeout: 60_000 });
      expect(video.status(), `видео /guides/${g.id}.mp4`).toBe(200);
      expect(video.headers()['content-type'] ?? '').toContain('video/mp4');

      const mp4 = parseMp4(await video.body());
      expect(Math.abs(mp4.seconds - g.seconds), `длительность ${mp4.seconds.toFixed(1)} с, эталон ${g.seconds} ±${TOLERANCE}`).toBeLessThanOrEqual(TOLERANCE);
      expect(mp4.handlers, 'дорожки (hdlr)').toEqual(expect.arrayContaining(['vide', 'soun']));
      expect(mp4.codecs, 'кодеки (stsd): видео H.264, звук AAC').toEqual(expect.arrayContaining(['avc1', 'mp4a']));
    });
  }
});
